from taf.sw.nadcm.provider import NADCMProvider


class NADCMConnection(object):
    def __init__(self, host, username, password, nadcm_version='nadcm_v1', timeout=60):
        self._nadcm = NADCMProvider.create_nadcm(host, username, password, nadcm_version, timeout)

    def disconnect(self, timeout=60):
        """
        Disconnect the connection.

        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        self._nadcm.disconnect(timeout=timeout)

    def get_inventory_nodes(self, timeout=60):
        """
        Retrieve the devices data in inventory.

        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: List with devices data per device.
              Example for part of the device data:
              ::

                [
                  {
                    'id': '634cb6e5024a1f378784b4a9',
                    'allocation': {},
                    'tags': [],
                    'name': 'FHGW-10707',
                    'serial_number': 'QTFCWN105000F',
                    'board_serial': 'ZWN10300014',
                    'full_product_name': 'AE-FHGW-A/AF1808.02',
                    'product_name': 'FHGW',
                    'manufacturer': 'Nokia Solutions and Networks',
                    'obm_ip': '10.108.204.22',
                    'obm_mac': '0c:7c:28:23:42:a5',
                    'inventory_node_type': 'computer_node',
                    'firmware_versions': {
                                          'BIOSVersion': '3.24.00',
                                          'CPLDVersion': '02_03_03',
                                          'FirmwareRevision': '4.35.00',
                                          'bank_a': '4.35.00',
                                          'bank_b': '4.31.00',
                                          'bios_a': '3.24.00',
                                          'bios_b': '3.24.00',
                                          'current': '4.35.00',
                                          'current_bios': '3.24.00',
                                          'current_bios_source': 'bios_a',
                                          'current_boot_source': 'bank_a'
                                        }
                    'dynamicstate': {
                                      'alarmhighest': 'warning',
                                      'bmc_firmware_activation': False,
                                      'bmc_reset': False,
                                      'configuring': False,
                                      'connectivity': 'PingHostOk',
                                      'inspecting': False,
                                      'powercycling': False,
                                      'powerstatus': 'on'
                                      }
                  }
                ]
        """
        return self._nadcm.get_inventory_nodes(timeout=timeout)

    def get_sensor_data(self, node_id, timeout=60):
        """
         Retrieve the sensor data with the given node id.

        :param str node_id: the ID of the device (inventory database ID)
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with sensor data including fan_sensors, power_sensors, temperature_sensors, voltage_sensors.
                Example:
                ::

                 {
                  'data': [
                    {
                      'type': 'airflow_sensors',
                      'sensors': None
                    },
                    {
                      'type': 'current_sensors',
                      'sensors': [
                        {
                          'name': 'hsc_current',
                          'number': '242',
                          'time': 1681883662,
                          'unit': 'amps',
                          'lower_c': 0,
                          'lower_nc': 0,
                          'lower_nr': 0,
                          'upper_c': 33.29,
                          'upper_nc': 0,
                          'upper_nr': 0,
                          'value': 6.79,
                          'status': 'ok',
                          'severity': 'ok'
                        }
                      ]
                    },
                    {
                      'type': 'fan_sensors',
                      'sensors': [
                        {
                          'name': 'fan_sys3_1',
                          'number': '199',
                          'time': 1681883662,
                          'unit': 'rpm',
                          'lower_c': 750,
                          'lower_nc': 1500,
                          'lower_nr': 0,
                          'upper_c': 0,
                          'upper_nc': 0,
                          'upper_nr': 0,
                          'value': 7800,
                          'status': 'ok',
                          'severity': 'ok'
                        }
                      ]
                    }]
                  }
        """
        return self._nadcm.get_sensor_data(node_id, timeout=timeout)

    def get_server_cups_data(self, node_id, timeout=60):
        """
        Retrieve cups data.

        :param str node_id: the ID of the device (inventory database ID)
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with cups data.
                Example:
                ::

                  {
                    'time': 0,
                    'cpu': 0,
                    'io': 0,
                    'memory': 0
                  }
        """
        return self._nadcm.get_server_cups_data(node_id, timeout=timeout)

    def get_node_power_state(self, node_id, timeout=60):
        """
        Retrieve node power state.

        :param str node_id: the ID of the device (inventory database ID)
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with power state.
                 Example:
                 ::

                    {'ok': True, 'protocol': 'afrest', 'value': 'on'}
        """
        return self._nadcm.get_node_power_state(node_id, timeout=timeout)

    def set_node_power_state(self, node_id, power_state, timeout=60):
        """
        Set the power state of a device.

        :param str node_id: the ID of the device (inventory database ID)
        :param str power_state: power operation to be executed, one of  ["on", "off", "forceoff", "reset"]
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with the operation status and used protocol.
                 Example:
                 ::

                   {
                     "ok": true,
                     "protocol": "redfish"
                   }
        """
        return self._nadcm.set_node_power_state(node_id, power_state, timeout=timeout)

    def get_supported_bmc_setting(self, node_id, timeout=60):
        """
        Get a list of supported BMC settings.

        :param str node_id: inventory node ID.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: List with each supported BMC setting.
                Example:
                ::

                  [
                    {
                      "name": "network_config",
                      "description": "Displays the BMC network settings (address source, address, subnet mask, default gw)",
                      "ops": [
                        {
                          "values": [
                            "on"
                          ],
                          "type": "read"
                        }
                      ]
                    }
                  ]
        """
        return self._nadcm.get_supported_bmc_setting(node_id, timeout=timeout)

    def get_supported_bios_setting_list(self, node_id, timeout=60):
        """
        Get a list of supported BIOS settings.

        :param str node_id: inventory node ID.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: List with each supported BIOS setting.
                Example:
                ::

                 [
                   {
                     'description': 'Enable/Disable IPv6 HTTP boot support. If disabled, IPv6 HTTP boot support will not be available.',
                     'name': 'NWSK007: Ipv6 HTTP Support',
                     'ops': [
                       {
                         'method': 'redfish',
                         'type': 'read',
                         'values': [
                           'Disabled',
                           'Enabled'
                         ]
                       },
                       {
                         'method': 'redfish',
                         'type': 'write',
                         'values': [
                           'Disabled',
                           'Enabled'
                         ]
                       }
                     ]
                   }
                 ]
        """
        return self._nadcm.get_supported_bios_setting_list(node_id, timeout=timeout)

    def get_bios_setting_with_given_setting_name(self, node_id, setting_name, timeout=60):
        """
        Get the current value of the given BIOS setting.

        :param str node_id: inventory node ID
        :param str setting_name: the name of the BIOS setting (from BIOS settings list)
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with the current value of BIOS setting.
                 Example:
                 ::

                    {
                      "value": "on"
                    }
        """
        return self._nadcm.get_bios_setting_with_given_setting_name(node_id, setting_name, timeout=timeout)

    def change_bios_setting(self, node_id, target_setting_name, new_setting_value, timeout=60):
        """
        Set the BIOS setting to the given value.

        :param str node_id: inventory node ID
        :param str target_setting_name: target setting name
        :param str new_setting_value: the new value for the setting
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with operation status.
                 Example:
                 ::

                    {
                      "status": "OK"
                    }
        """
        return self._nadcm.change_bios_setting(node_id, target_setting_name, new_setting_value, timeout=timeout)

    def get_active_events(self, timeout=60):
        """
        Get the active events.

        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: list with each event.
                Example:
                ::

                  {
                    "lastid": "",
                    "events": [
                      {
                        "timestampiso": "2023-06-06T08:23:26Z",
                        "id": "647eed34e1f345d7a069b4e7",
                        "record_id": "137c897957a4f763",
                        "device_id": "64631da226c6d31e116bd7f7",
                        "sel_timestamp": 1686039806,
                        "read_timestamp": 1686039860,
                        "sensor_name": "Login Info",
                        "sensor_type": "Login failed",
                        "sensor_number": 2,
                        "description": "Login failed -- Account: admin from IP:10.110.23.251",
                        "event_type": "discrete",
                        "event_direction": "Assertion",
                        "magic_alarm_id": 2,
                        "active": true,
                        "event_number": 1999,
                        "severity": "warning",
                        "origin": "sel",
                        "node_type": "computer_node",
                        "server": "10.71.169.29",
                        "rack": "AH05",
                        "ulocation": "3",
                        "cleared": false,
                        "alarm_info": {
                          "action": "NoAction"
                        }
                      }
                    ]
                  }
        """
        return self._nadcm.get_active_events(timeout=timeout)

    def get_active_events_for_node(self, node_ip, timeout=60):
        """
        Get active events of one node.

        :param str node_ip: server ip address
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: list with each event.
                Example:
                ::

                  {
                    "lastid": "",
                    "events": [
                      {
                        "timestampiso": "2023-06-06T08:23:26Z",
                        "id": "647eed34e1f345d7a069b4e7",
                        "record_id": "137c897957a4f763",
                        "device_id": "64631da226c6d31e116bd7f7",
                        "sel_timestamp": 1686039806,
                        "read_timestamp": 1686039860,
                        "sensor_name": "Login Info",
                        "sensor_type": "Login failed",
                        "sensor_number": 2,
                        "description": "Login failed -- Account: admin from IP:10.110.23.251",
                        "event_type": "discrete",
                        "event_direction": "Assertion",
                        "magic_alarm_id": 2,
                        "active": true,
                        "event_number": 1999,
                        "severity": "warning",
                        "origin": "sel",
                        "node_type": "computer_node",
                        "server": "10.71.169.29",
                        "rack": "AH05",
                        "ulocation": "3",
                        "cleared": false,
                        "alarm_info": {
                          "action": "NoAction"
                        }
                      }
                    ]
                  }
        """
        return self._nadcm.get_active_events_for_node(node_ip=node_ip, timeout=timeout)

    def get_node_credentials(self, node_id, timeout=60):
        """
        Get the credential of one node including managements, redfish, snmptrap and snmpv3. The credential is\
        used for NADCM to access the device.\

        :param str node_id: node id in inventory.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with credentials.
                Example:
                ::

                 {
                      "community": "public",
                      "hypervisor": {
                        "pass": "",
                        "user": ""
                      },
                      "id": "64631ddee286afa00a073e0c",
                      "nodeid": "64631dde26c6d31e116bd7fa",
                      "pass": "CNnokia_nokiaCN123",
                      "redfish": {
                        "user": "Administrator",
                        "pass": "CNnokia_nokiaCN123"
                      },
                      "snmptrap": {
                        "authkey": "",
                        "authprotocol": "",
                        "community": "",
                        "engineid": "",
                        "privkey": "",
                        "privprotocol": "",
                        "securitylevel": "",
                        "securityname": "",
                        "version": ""
                      },
                      "snmpv3": {
                        "securityname": "",
                        "authkey": "",
                        "privkey": "",
                        "securitylevel": "",
                        "authprotocol": "",
                        "privprotocol": ""
                      },
                      "user": "admin"
                    }
        """
        return self._nadcm.get_node_credentials(node_id=node_id, timeout=timeout)

    def change_node_management_credential(self, node_id, user, password, timeout=60):
        """
        Changing management credential(IPMI/REST/SSH/gNMI) for one node. The credential is used for NADCM\
        to access the device.

        :param str node_id: node id in inventory.
        :param str user: username of management.
        :param str password: password of management.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        return self._nadcm.change_node_management_credential(node_id=node_id,
                                                             user=user,
                                                             password=password,
                                                             timeout=timeout)

    def change_redfish_credential(self, node_id, user, password, timeout=60):
        """
        Changing redfish credential for one node. The credential is used for NADCM to access the device.

        :param str node_id: node id in inventory.
        :param str user: username of redfish.
        :param str password: password of redfish.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        return self._nadcm.change_redfish_credential(node_id=node_id,
                                                     user=user,
                                                     password=password,
                                                     timeout=timeout)

    def reset_node_bmc(self, node_id, upgrade_type='bmc_reset', timeout=60):
        """
        trigger node BMC reset.

        :param str node_id: the inventory node id
        :param str upgrade_type: the default value is bmc_reset.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return str: task id
        """
        return self._nadcm.reset_node_bmc(node_id=node_id, upgrade_type=upgrade_type, timeout=timeout)

    def get_upgrade_state(self, task_id, timeout=60):
        """
        Check the status of the given upgrade task.

        :param str task_id: operation task id
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return Dict: the status of the given upgrade task
                    Example:
                    ::

                     {
                      'current': 5,
                      'message': '',
                      'result': 'success',
                      'result_file_id': '',
                      'state': 'SUCCESS',
                      'status': 'Task completed',
                      'steps': [
                        'Checking server credentials',
                        'Resetting the BMC',
                        'Waiting for the BMC to come back up',
                        'Re-reading node details',
                        'Checking node inspection status'
                      ],
                      'substatus': '',
                      'total': 5
                     }
        """
        return self._nadcm.get_upgrade_state(task_id=task_id, timeout=timeout)

    def get_events(self, since=None, limit=None, severity_list=None, device_name_list=None, timeout=60, **filter):
        """
        get all events

        :param int since: Optional, unix timestamp to filter events created after this time. It can be get by "date +%s". \
          e.g.1699438046.
        :param int limit: Optional, maximum number of events to retrieve.
        :param list severity_list: Optional, list of severity levels to filter events, eg. ["warning","critical"].
        :param list device_name_list: Optional, list of device names to filter events. eg. ["dev_name1", "dev_name2"].
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :param filter: Optional, additional key-value pairs for filtering events. eg. active="true".
        :return: list with each event.
                Example:
                ::

                 {
                   "lastid": "",
                   "events": [
                     {
                       "timestampiso": "2023-06-06T08:23:26Z",
                       "id": "647eed34e1f345d7a069b4e7",
                       "record_id": "137c897957a4f763",
                       "device_id": "64631da226c6d31e116bd7f7",
                       "sel_timestamp": 1686039806,
                       "read_timestamp": 1686039860,
                       "sensor_name": "Login Info",
                       "sensor_type": "Login failed",
                       "sensor_number": 2,
                       "description": "Login failed -- Account: admin from IP:10.110.23.251",
                       "event_type": "discrete",
                       "event_direction": "Assertion",
                       "magic_alarm_id": 2,
                       "active": true,
                       "event_number": 1999,
                       "severity": "warning",
                       "origin": "sel",
                       "node_type": "computer_node",
                       "server": "10.71.169.29",
                       "rack": "AH05",
                       "ulocation": "3",
                       "cleared": false,
                       "alarm_info": {
                         "action": "NoAction"
                       }
                     }
                   ]
                 }
        """
        return self._nadcm.get_events(since, limit, severity_list, device_name_list, timeout=timeout, **filter)

    def get_events_for_node(self, node_ip, since=None, timeout=60):
        """
        get all events by given node ip address

        :param str node_ip: node ip address
        :param int since: Optional, the start timestamp which can be get by "date +%s", e.g. 1699438046. Default is None.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: list with each event.
                Example:
                ::

                 {
                   "lastid": "",
                   "events": [
                     {
                       "timestampiso": "2023-06-06T08:23:26Z",
                       "id": "647eed34e1f345d7a069b4e7",
                       "record_id": "137c897957a4f763",
                       "device_id": "64631da226c6d31e116bd7f7",
                       "sel_timestamp": 1686039806,
                       "read_timestamp": 1686039860,
                       "sensor_name": "Login Info",
                       "sensor_type": "Login failed",
                       "sensor_number": 2,
                       "description": "Login failed -- Account: admin from IP:10.110.23.251",
                       "event_type": "discrete",
                       "event_direction": "Assertion",
                       "magic_alarm_id": 2,
                       "active": true,
                       "event_number": 1999,
                       "severity": "warning",
                       "origin": "sel",
                       "node_type": "computer_node",
                       "server": "10.71.169.29",
                       "rack": "AH05",
                       "ulocation": "3",
                       "cleared": false,
                       "alarm_info": {
                         "action": "NoAction"
                       }
                     }
                   ]
                 }
        """
        return self._nadcm.get_events_for_node(node_ip=node_ip, since=since, timeout=timeout)

    def upload_a_file(self, file_name, data, timeout=60):
        """
        Upload file to NADCM

        :param str file_name: local file name
        :param data data: file data
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return str: file id, example: 6752a0968e120f96daf2a101
        """
        return self._nadcm.upload_a_file(file_name=file_name, data=data, timeout=timeout)

    def add_file_metadata_by_id(self, file_id, file_type, hw_profiles, release_id="", timeout=60):
        """
        Modify file info on NADCM

        :param str file_id: file id
        :param str file_type: file type, such as dell_binary, hpe_binary, cpld_fw
        :param str hw_profiles: HW profiles, such DELL, HPE, BPS NAC2006-01
        :param str release_id: release id
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return dict: file info.
                    Example:
                    ::

                     {
                       'id': '6752a51a8e120f96daf2a12d',
                       'metadata': {
                         'md5': '80eccd15a36262e79b837479f959aef1',
                         'release_ids': '',
                         'sha256': '3c33bd7d05870c9e6fecbab9f97ca37efbe274ec26a16d566ff60a0ba7f316f7',
                         'status': 'ProcessingDone',
                         'upgrade_file_type': 'hpe_binary',
                         'upgrade_product_names': [
                           'HPE ProLiant'
                         ]
                       }
                     }
        """
        return self._nadcm.add_file_metadata_by_id(file_id=file_id,
                                                   file_type=file_type,
                                                   hw_profiles=hw_profiles,
                                                   release_id=release_id,
                                                   timeout=timeout)

    def delete_file_by_id(self, file_id, timeout=60):
        """
        Delete file from NADCM

        :param str file_id: file id
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        return self._nadcm.delete_file_by_id(file_id=file_id, timeout=timeout)

    def list_files(self, field, value, timeout=60):
        """
        Get files info on NADCM.

        :param str field: name of a field in file data used to filter the search.
        :param str value: value of a field in file data used to filter the search.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return list: file info.
                    Example:
                    ::

                     [
                       {
                         "id": "673daca8576a3a9f89b26622",
                         "chunkSize": 261120,
                         "uploadDate": "2024-11-20T09:32:24.283Z",
                         "length": 6273,
                         "md5": "b1c7ba9755fe13301a5a54a272623dae",
                         "filename": "AO-S3048ON-A_AO-R12S12J-A_U18_S_O17.conf.tpl",
                         "metadata": {
                           "description": "Template file for switch initial configuration. Download this, \
                                           make the necessary changes, and upload as a switch configfile.",
                           "md5": "b1c7ba9755fe13301a5a54a272623dae",
                           "sha256": "d27f3f6086467ba8efabaec3f7884770f5bec8cbdffe6da0cba081e7dd36b438",
                           "upgrade_file_type": "switch_conf_template"
                         }
                       },
                       {
                         "id": "673daca8576a3a9f89b26626",
                         "chunkSize": 261120,
                         "uploadDate": "2024-11-20T09:32:24.358Z",
                         "length": 7320,
                         "md5": "af60c3fc8ba385000c111db68ee6f16f",
                         "filename": "AO-S3048ON-A_AO-R39S3J-A_U32_H_O17.conf.tpl",
                         "metadata": {
                           "description": "Template file for switch initial configuration. Download this, \
                                           make the necessary changes, and upload as a switch configfile.",
                           "md5": "af60c3fc8ba385000c111db68ee6f16f",
                           "sha256": "181c103c8b4dc5cc679b455b2b1076890f623451406863d8ec988b2c6f043956",
                           "upgrade_file_type": "switch_conf_template"
                         }
                       }
                     ]
        """
        return self._nadcm.list_files(field=field, value=value, timeout=timeout)

    def device_query(self, timeout=60, **kwargs):
        """
        Get devices info.

        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :param dict kwargs: key str- query parameters, supported: filter, select, sort, reduce, limit, iter
                            value str - values to each parameters
                            if kwargs is None or {}, will return all devices info
        :return dict: devices info
                Example for part of the device data:
                ::

                 {
                     "metadata": {
                         "iter": "invalid",
                         "more-data": false
                     },
                     "data": [
                       {
                         'id': '634cb6e5024a1f378784b4a9',
                         'allocation': {},
                         'tags': [],
                         'name': 'FHGW-10707',
                         'serial_number': 'QTFCWN105000F',
                         'board_serial': 'ZWN10300014',
                         'full_product_name': 'AE-FHGW-A/AF1808.02',
                         'product_name': 'FHGW',
                         'manufacturer': 'Nokia Solutions and Networks',
                         'obm_ip': '10.108.204.22',
                         'obm_mac': '0c:7c:28:23:42:a5',
                         'inventory_node_type': 'computer_node',
                         'firmware_versions': {
                                               'BIOSVersion': '3.24.00',
                                               'CPLDVersion': '02_03_03',
                                               'FirmwareRevision': '4.35.00',
                                               'bank_a': '4.35.00',
                                               'bank_b': '4.31.00',
                                               'bios_a': '3.24.00',
                                               'bios_b': '3.24.00',
                                               'current': '4.35.00',
                                               'current_bios': '3.24.00',
                                               'current_bios_source': 'bios_a',
                                               'current_boot_source': 'bank_a'
                                             }
                         'dynamicstate': {
                                           'alarmhighest': 'warning',
                                           'bmc_firmware_activation': False,
                                           'bmc_reset': False,
                                           'configuring': False,
                                           'connectivity': 'PingHostOk',
                                           'inspecting': False,
                                           'powercycling': False,
                                           'powerstatus': 'on'
                                           }
                       }
                     ]
                 }
        """
