    def reset_rannic_card(self, node_id: str, rannic_location: str = "1", reset_type: str = "warm", timeout=60):
        """
        Reset RANNIC card.

        .. admonition:: API used:
           :collapsible: closed

           POST `/gordon/upgrade`_

            .. _/gordon/upgrade:
             https://wrgitlab.ext.net.nokia.com/TAF/openapi-specs/nadcm_spec/-/blob/master/gordon_openapi.yaml

           **Note:** The used 'rannic_accelerator_reset' operation is missing from the API documentation.
           Keyword documentation should be updated once `CISUP-1524`_ is resolved.

            .. _CISUP-1524:
             https://jiradc.ext.net.nokia.com/projects/CISUP/issues/CISUP-1524.

        :param str node_id: the ID of the device (inventory database ID)
        :param str rannic_location: Optional, RANNIC location. Default is '1'. Examples: '1', '2', '199-0'
        :param str reset_type: Optional, reset type. Default is 'warm'. Examples: 'warm', 'cold'
        :param Union[int,str] timeout: Optional, timeout in seconds for request, default is '60s'.
        :param Union[NADCMConnection, str] connection: NADCMConnection object or if used, string name alias.

        :return str: status URI for the started operation, example: /gordon/status/5dbcbe44-23d2-46c9-914c-496c606d4907
        """
        return self._nadcm.reset_rannic_card(node_id=node_id, rannic_location=rannic_location,
                                             reset_type=reset_type, timeout=timeout)

