    def set_management_credentials(self, node_id, username, password, privilege=None, force_change=True, timeout=60):
        """
        Set management credential for the given node id via NADCM. If the user not exists, will create a new one. Dell and HPE devices\
        are not supported.

        :param str node_id: the node id.
        :param str username: the user name.
        :param str password: the password.
        :param str privilege: Optional, the privilege. eg."administrator", "operator", "user". Default is "administrator"
        :param bool force_change: Optional, the force change. Default is True.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: dict.
              Example:
              ::

                {
                    "status": "OK"
                }
        """
        return self._nadcm.set_management_credentials(node_id, username, password, privilege, force_change, timeout=timeout)

    def delete_management_credentials(self, node_id, username, timeout=60):
        """
        Delete the management credentials for the given node via NADCM.

        :param str node_id: the node id.
        :param str username: the username.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: dict.
              Example:
              ::

                {
                    "status": "OK"
                }
        """
        return self._nadcm.delete_management_credentials(node_id, username, timeout=timeout)

