    def create_default_credentials(self, deftype, timeout=60, **kwargs):
        """
        Creates new default credentials for a deftype.

        :param str deftype: the type of the credentials. eg. "any", "Dell", "HPE", "AMI".
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param str user: Optional, the management user.
        :param str password: Optional, the management password.
        :param str community: Optional, SNMP version 2 Community string.
        :param str redfish_user: Optional, the redfish username.
        :param str redfish_pass: Optional, the redfish password.
        :param str snmpv3_securityname: Optional, SNMP v3 security name.
        :param str snmpv3_authkey: Optional, SNMP v3 authentication pass phrase.
        :param str snmpv3_privkey: Optional, SNMP v3 privacy pass phrase.
        :param str snmpv3_securitylevel: Optional, SNMP v3 security level which defines the authentication and privacy model.
        :param str snmpv3_authprotocol: Optional, SNMP v3 authentication type (md5|sha).
        :param str snmpv3_privprotocol: Optional, SNMP v3 privacy type (des|aes).
        detail parameters can be checked in spec -> Credentials -> POST /v2/credentials/defaults part.
        https://wrgitlab.ext.net.nokia.com/TAF/openapi-specs/nadcm_spec/-/blob/master/inventory_openapi.yaml?ref_type=heads
        :return: None.
        """
        return self._nadcm.create_default_credentials(deftype, timeout=timeout, **kwargs)

    def update_default_credentials(self, deftype, timeout=60, **kwargs):
        """
        Modify the default credentials for a deftype.

        :param str deftype: the type of the credentials. eg. "any", "Dell", "HPE", "AMI".
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param str user: Optional, the management user.
        :param str password: Optional, the management password.
        :param str community: Optional, SNMP version 2 Community string.
        :param str redfish_user: Optional, the redfish username.
        :param str redfish_pass: Optional, the redfish password.
        :param str snmpv3_securityname: Optional, SNMP v3 security name.
        :param str snmpv3_authkey: Optional, SNMP v3 authentication pass phrase.
        :param str snmpv3_privkey: Optional, SNMP v3 privacy pass phrase.
        :param str snmpv3_securitylevel: Optional, SNMP v3 security level which defines the authentication and privacy model.
        :param str snmpv3_authprotocol: Optional, SNMP v3 authentication type (md5|sha).
        :param str snmpv3_privprotocol: Optional, SNMP v3 privacy type (des|aes).
        detail parameters can be checked in spec -> Credentials -> PUT /v2/credentials/defaults/type/{type} part.
        https://wrgitlab.ext.net.nokia.com/TAF/openapi-specs/nadcm_spec/-/blob/master/inventory_openapi.yaml?ref_type=heads
        :return: None.
        """
        return self._nadcm.update_default_credentials(deftype, timeout=timeout, **kwargs)

    def delete_default_credentials(self, deftype, timeout=60):
        """
        Delete the default credentials for a deftype.

        :param str deftype: the type of the credentials. eg. "any", "Dell", "HPE", "AMI".
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None.
        """
        return self._nadcm.delete_default_credentials(deftype, timeout=timeout)

    def set_device_access_credentials(self, node_id, timeout=60, **kwargs):
        """
        Set device credentials data. It is used for NADCM to access the device. Reminder that if you provide\
        partial of the credential info in the kwargs, the rest of the info will be set to default value.

        :param str node_id: the node id.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param str id: Optional, Database id of device specific credential.
        :param str user: Optional, the management user.
        :param str password: Optional, the management password.
        :param str community: Optional, SNMP version 2 Community string.
        :param dict redfish: Optional, the redfish credential. eg. {'pass': 'cmb9.admin', 'user': 'root'}
        :param dict snmptrap: Optional, SNMP v3 info. eg. {'authkey': '','authprotocol': '','community': '','engineid': '',
              'privkey': '','privprotocol': '','securitylevel': '','securityname': '','version': ''}
        :param dict snmpv3: Optional, SNMP version 3 credential information. eg. {"securityname": "secname","authkey": "authkey",\
              "privkey": "privkey","securitylevel": "authpriv","authprotocol": "sha","privprotocol": "aes"}
        detail parameters can be checked in spec -> Credentials -> POST /v1/credentials/id/{id} part.
        https://wrgitlab.ext.net.nokia.com/TAF/openapi-specs/nadcm_spec/-/blob/master/inventory_openapi.yaml?ref_type=heads
        :return: None.
        """
        return self._nadcm.set_device_access_credentials(node_id, timeout=timeout, **kwargs)

    def update_device_access_credentials(self, node_id, timeout=60, **kwargs):
        """
        Update the device credentials data. It is used for NADCM to access the device.

        :param str node_id: the node id.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param str id: Optional, Database id of device specific credential.
        :param str user: Optional, the management user.
        :param str password: Optional, the management password.
        :param str community: Optional, SNMP version 2 Community string.
        :param str redfish_user: Optional, the redfish username.
        :param str redfish_pass: Optional, the redfish password.
        :param str snmpv3_securityname: Optional, SNMP v3 security name.
        :param str snmpv3_authkey: Optional, SNMP v3 authentication pass phrase.
        :param str snmpv3_privkey: Optional, SNMP v3 privacy pass phrase.
        :param str snmpv3_securitylevel: Optional, SNMP v3 security level which defines the authentication and privacy model.
        :param str snmpv3_authprotocol: Optional, SNMP v3 authentication type (md5|sha).
        :param str snmpv3_privprotocol: Optional, SNMP v3 privacy type (des|aes).
        :param str snmpv3_securityname: Optional, SNMP v3 security name.
        detail parameters can be checked in spec -> Credentials -> POST /v1/credentials/id/{id} part.
        https://wrgitlab.ext.net.nokia.com/TAF/openapi-specs/nadcm_spec/-/blob/master/inventory_openapi.yaml?ref_type=heads
        :return: None.
        """
        return self._nadcm.update_device_access_credentials(node_id, timeout=timeout, **kwargs)

    def get_hwscan_address_ranges(self, timeout=60):
        """
        Get a list of address ranges that are monitored.

        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return list: each item in the list is a dict, include the hardware scan address ranges.
                Example:
                ::

                  [
                      {
                          "id": "57f40855a86b3b0001b340e6",
                          "notes": "IPv4 address range",
                          "first_addr": "192.168.1.10",
                          "last_addr": "192.168.1.100",
                          "enabled": true
                      }
                  ]
        """
        return self._nadcm.get_hwscan_address_ranges(timeout=timeout)

    def create_hwscan_address_range(self, first_addr, last_addr, timeout=60, **kwargs):
        """
        Add range of addresses to be monitored. The range can be IPv4 address range or IPv6 address range.\
        If the optional deftype parameter is assigned, the HW is configured with the credentials from the\
        specified deftype credential set after the scan. If parameter is not specified credentials from any\
        global credential set is used as default behaviour.

        :param str first_addr: the first address in the range. IPv4 or IPv6 address.
        :param str last_addr: the last address in the range. IPv4 or IPv6 address.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param str notes: Optional, notes about the address range.
        :param bool enabled: Optional, whether to enable auto scan.
        :param str deftype: Optional, the credential type.
        Detail parameters can be checked in spec -> Configuration -> POST /v1/config/addresses part.\
            https://wrgitlab.ext.net.nokia.com/TAF/openapi-specs/nadcm_spec/-/blob/master/hwscan_openapi.yaml?ref_type=heads
        :return dict: A dictionary of the id of the new address range
                Example:
                ::

                  {
                      "id": "57f40855a86b3b9001b340e6"
                  }
        """
        return self._nadcm.create_hwscan_address_range(first_addr, last_addr, timeout=timeout, **kwargs)

    def delete_hwscan_address_range(self, range_id, timeout=60):
        """
        Delete an IPv4 or IPv6 address range.

        :param str range_id: the id of the address range.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        return self._nadcm.delete_hwscan_address_range(range_id, timeout=timeout)

