    def delete_node(self, node_id, timeout=60):
        """
        Delete node.

        :param str node_id: the ID of the device (inventory database ID)
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        return self._nadcm.delete_node(node_id=node_id, timeout=timeout)

    def get_server_led_status(self, node_id, led_id, timeout=60):
        """
        Get server identify LED status.

        :param str node_id: the ID of the device (inventory database ID)
        :param str led_id: the ID of the LED, for idrac, it is 1, for bmc it is 2.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with LED status
            Example:
              ::

                {
                    "value": "off"
                }
        """
        return self._nadcm.get_server_led_status(node_id=node_id, led_id=led_id, timeout=timeout)

    def set_server_led_status(self, node_id, led_id, value, timeout=60, **kwargs):
        """
        Set server identify LED status.

        :param str node_id: the ID of the device (inventory database ID)
        :param str led_id: the ID of the LED, for idrac, it is 1, for bmc it is 2.
        :param str value: the value of the LED, on, off or blinking.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param Union[int,str] duration: Optional, status period of time (seconds).
        :return: Dict of command status, example: {"status": "OK"}
        """
        return self._nadcm.set_server_led_status(node_id=node_id, led_id=led_id, value=value, timeout=timeout, **kwargs)

    def get_supported_boot_devices(self, node_id, timeout=60):
        """
        Get current boot parameters.

        :param str node_id: the ID of the device (inventory database ID)
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with boot parameters
            Example:
            ::

                {
                    "supported_boot_devices": [
                        "cdrom",
                        "bios",
                        "safe",
                        "disk",
                        "pxe"
                    ],
                    "efiboot_supported": true,
                    "legacy_supported": true
                }
        """
        return self._nadcm.get_supported_boot_devices(node_id=node_id, timeout=timeout)

    def set_boot_parameters(self, node_id, boot_device, timeout=60, **kwargs):
        """
        Set boot parameters.

        :param str node_id: the ID of the device (inventory database ID)
        :param str boot_device: the new boot device, supported boot devices can be get by get_supported_boot_devices.
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param bool efiboot: Optional, indicates whether or not UEFI boot mode is requested. If UEFI boot mode is desired to be\
            set on or off, the 'efiboot' parameter should be present (with True or False value). If it is absent, boot mode setting\
            is not modified.
        :param bool persistent: Optional, indicates the desired persistence of the new boot parameters' setting. This parameter is\
            adviced not to be used, as the interrogation of the boot parameters from the node may show misleading information after\
            a reboot (it may not show that the boot device and boot mode are persistently set). If absent, it is interpreted as False.
        :return: Dict of boot parameters.
            Example:
            ::

                {
                    "boot_device": "disk",
                    "persistent": true,
                    "efiboot": true
                }
        """
        return self._nadcm.set_boot_parameters(node_id=node_id, boot_device=boot_device, timeout=timeout, **kwargs)

    def get_boot_parameters(self, node_id, timeout=60):
        """
        Get current boot parameters.

        :param str node_id: the ID of the device (inventory database ID)
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: Dict with boot parameters
            Example:
            ::

                {
                    "boot_device": "disk",
                    "persistent": true,
                    "efiboot": true
                }
        """
        return self._nadcm.get_boot_parameters(node_id=node_id, timeout=timeout)

    def start_data_export(self, timeout=60, **kwargs):
        """
        Exports the data from selected components into a json, gzip or xlsx file.

        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param list select: Optional, select multiple targets for export. Items enum: inventory, credentials, events, active-events, devicedump,\
            sensors, systemconfig, eventrules, notificationrules, certificates, hwallocations, activitylog. If absent, it is interpreted as all.
        :param str method: Optional, the format of the export file. eg. export-json, export-xlsx, export-zip. If absent, it is interpreted as\
            export-json.
        :param str nodeid: Optional, required for devicedump. Device ID for running devicedump. eg. 65e9b0b4a1061a95fdd56258.
        :param str collect: Optional, the type of data to be collected. eg. debuglogs.
        :param str key: Optional, >= 8 characters, passphrase for credentials encryption, needed for inventory, credentials, systemconfig and\
            certificates. e.g., 12345678
        :param str filter: Optional, filter string, applicable to events and activitylog only. e.g. and(eq(active, true), and(eq(devicename,\
            'RM20test'))).
        :param str include-sensitive-info: Optional, applicable only for Dell device with the devicedump target and collect=debuglogs value\
            selected. Enabling this parameter may include some sensitive information in the exported troubleshooting device data. By default,\
            this parameter is set to No and user sensitive data is excluded from the device data collected from Dell. e.g. Yes, No.
        :param str days: Optional, download the last N days of the troubleshooting logs, from today's date. e.g 7. Applicable only for HPE device\
            with the devicedump target and the collect=debuglogs value selected. Only one type of filter, either days or from and to can be used\
            at a time. If both are provided, the days filter will take precedence. The device itself performs the validation of this filter.
        :param str from: Optional, start date for the devicedump collection for HP devices. Date should be in YYYY-MM-DD format. e.g 2014-03-01.\
            Applicable only for HPE device with the devicedump target and collect=debuglogs value selected. The device itself performs the\
            validation of this filter. 'days' parameters should not be used with this query parameter.
        :param str to: Optional, end date for the devicedump collection for HP devices. Date should be in YYYY-MM-DD format. e.g 2014-03-30.\
            applicable only for HPE device with the devicedump target and collect=debuglogs value selected.The device itself performs the\
            validation of this filter. 'days' parameters should not be used with this query parameter.
        :return dict: Task info.
            Example:
            ::

                {
                    "taskid": "3328451335138149956",
                    "statusurl": "status?id=3328451335138149956"
                }
        """
        return self._nadcm.start_data_export(timeout=timeout, **kwargs)

    def get_export_task_status(self, task_id, timeout=60):
        """
        Get the status of the export task by ID.

        :param str task_id: task id. It can be get from "start_data_export".
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return dict: export task status.
            Example:
              ::

                {
                    "id": 1682953287285240600,
                    "status": "Running",
                    "substatus": {
                        "inventory": {
                            "id": "inventory",
                            "status": "Running",
                            "error": "err",
                            "addl_error_info": null,
                            "resulturl": "result?id=1682953287285240679",
                            "removedaftermins": 5
                        },
                        "notificationrules": {
                            "id": "notificationrules",
                            "status": "Running",
                            "error": "err",
                            "addl_error_info": null,
                            "resulturl": "result?id=1682953287285240679",
                            "removedaftermins": 5
                        }
                    },
                    "method": "export-json"
                }
        """
        return self._nadcm.get_export_task_status(task_id=task_id, timeout=timeout)

    def download_exported_data(self, task_id, file_path, timeout=60):
        """
        Downloads the exported content in a file format by task ID. Should use start_data_export to export data and get the task ID.\
        Then check the task status by get_export_task_status. After the task is completed, use this function to download the exported data.

        :param str task_id: task id. It can be get from "start_data_export".
        :param str file_path: the file name and path to save the downloaded data. eg. /tmp/exported_data.zip
        :param int timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        return self._nadcm.download_exported_data(task_id=task_id, file_path=file_path, timeout=timeout)
